import{_ as s,o as i,c as r,a3 as o,j as e,a as t}from"./chunks/framework.z_KJ15Ep.js";const a="/bilder/vorbereitung/noten-eines-abschnitts-loeschen.png",w=JSON.parse('{"title":"Noten eines ausgewählten Lernabschnitts löschen","description":"","frontmatter":{"title":"Noten eines ausgewählten Lernabschnitts löschen","source_pageid":830,"source_revision":2540},"headers":[],"relativePath":"zeugnisse/vorbereitung/noten-des-akt-abschnittes-loeschen-gruppenprozesse-noten-zeugnisvorbereitung.md","filePath":"zeugnisse/vorbereitung/noten-des-akt-abschnittes-loeschen-gruppenprozesse-noten-zeugnisvorbereitung.md"}'),l={name:"zeugnisse/vorbereitung/noten-des-akt-abschnittes-loeschen-gruppenprozesse-noten-zeugnisvorbereitung.md"};function h(c,n,u,g,d,p){return i(),r("div",null,[...n[0]||(n[0]=[o('<h1 id="noten-eines-ausgewahlten-lernabschnitts-loschen" tabindex="-1">Noten eines ausgewählten Lernabschnitts löschen <a class="header-anchor" href="#noten-eines-ausgewahlten-lernabschnitts-loschen" aria-label="Permalink to &quot;Noten eines ausgewählten Lernabschnitts löschen&quot;">​</a></h1><p><a href="/bilder/vorbereitung/noten-eines-abschnitts-loeschen.png"><img src="'+a+'" alt="Noten eines Abschnitts löschen mit ausdrücklicher Abschnittsauswahl" loading="lazy"></a></p><p><em>Noten eines Abschnitts löschen mit ausdrücklicher Abschnittsauswahl — Oberfläche von SchILD-NRW 3.6.0.</em></p><p>Mit <strong>Noten eines Abschnitts löschen</strong> entfernen Sie Zeugnisnoten und bei aktivierter Quartalsnotenanzeige auch Quartalsnoten der ausgewählten Schülergruppe. Teilleistungen bleiben dabei erhalten.</p><p>Die Löschung kann erforderlich sein, wenn Noten versehentlich eingetragen wurden oder eine Datenübertragung fehlerhaft war. Schulen mit Quartalsnoten, etwa Gesamtschulen und Sekundarschulen, müssen deren Anzeige zunächst in den <strong>Globalen Einstellungen</strong> aktivieren.</p><ol><li>Grenzen Sie die Schülerauswahl auf die Personen ein, deren Noten gelöscht werden sollen.</li><li>Starten Sie den Gruppenprozess <strong>Noten eines Abschnitts löschen</strong>.</li><li>Wählen Sie unter <strong>Abschnitt</strong> das gewünschte Halbjahr aus.</li><li>Legen Sie mit <strong>Zeugnisnoten löschen</strong> und, bei aktivierter Quartalsnotenanzeige, <strong>Quartalsnoten löschen</strong> fest, welche Notenarten entfernt werden. Sie können eine oder beide Notenarten auswählen.</li><li>Kontrollieren Sie Abschnitt und Auswahl und bestätigen Sie mit <strong>OK</strong>. Mit <strong>Abbrechen</strong> schließen Sie den Dialog ohne Löschung.</li></ol><p>Die Abbildung oben zeigt die Ansicht ohne Quartalsnotenauswahl. Bei aktivierter Quartalsnotenanzeige enthält der Dialog beide Auswahlfelder und warnt vor der Löschung der Zeugnisnoten beziehungsweise Quartalsnoten des ausgewählten Abschnitts.</p><p><strong>Teilleistungen werden nicht mitgelöscht.</strong> Dafür gibt es unter <strong>Gruppenprozesse → Teilleistungen</strong> den eigenen Prozess <a href="/schild3/suchen-gruppenprozesse/teilleistungen-fuer-einen-abschnitt-loeschen-gruppenprozesse-teilleistungen.html">Teilleistungen für einen Abschnitt löschen</a>. Auch dort wählen Sie den gewünschten Abschnitt aus.</p>',8),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),t("Hinweis")]),e("p",null,"Wie bei allen anderen Löschoperationen auch sollte zuvor eine Datensicherung in Erwägung gezogen werden.")],-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Noten_des_akt._Abschnittes_l%C3%B6schen_(Gruppenprozesse_Noten,_Zeugnisvorbereitung)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),t(" · Quellrevision 2540.")],-1)])])}const _=s(l,[["render",h]]);export{w as __pageData,_ as default};
